    avg_headcount = 343.1

    # Provided month-end headcounts by department are not given, so we use exit_event_date
    # to count separations per department in the window
    df['exit_event_date'] = pd.to_datetime(df['exit_event_date'], errors='coerce')

    exits_in_window = df[
        (df['exit_event_date'] >= window_start) &
        (df['exit_event_date'] <= window_end) &
        (df['row_kind'] == 'counted')
    ].copy()

    # Total separations in window
    total_separations = len(exits_in_window)

    # Separations by department
    dept_separations = exits_in_window.groupby('Department').size().reset_index(name='separations')

    # Overall attrition rate
    overall_attrition_rate = total_separations / avg_headcount

    # Per-department attrition rate: separations / avg_headcount (overall avg, as dept avg not provided)
    dept_separations['attrition_rate'] = dept_separations['separations'] / avg_headcount

    dept_results_sep = [
        {"name": str(row['Department']), "value": float(row['separations'])}
        for _, row in dept_separations.iterrows()
    ]

    dept_results_rate = [
        {"name": str(row['Department']), "value": round(float(row['attrition_rate']), 4)}
        for _, row in dept_separations.iterrows()
    ]

    # Add overall
    dept_results_sep.append({"name": "Overall", "value": float(total_separations)})
    dept_results_rate.append({"name": "Overall", "value": round(overall_attrition_rate, 4)})

    result['segments'].append({
        "segment_column": "Department",
        "metric_column": "exit_event_date",
        "aggregation": "count",
        "label": "separations_nov2025_oct2026",
        "results": dept_results_sep
    })

    result['segments'].append({
        "segment_column": "Department",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": dept_results_rate
    })

    result['assumptions'].append(
        "Attrition rate = separations (exit_event_date in Nov 2025–Oct 2026, row_kind='counted') / avg headcount 343.1 (provided)."
    )
    result['assumptions'].append(
        "Per-department attrition rate uses the overall average headcount (343.1) as department-level monthly headcounts were not provided."
    )
    result['assumptions'].append(
        "1 exit dated after 31 Oct 2026 excluded per domain rules."
    )

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

